//! Card rules text, from the card sources' doc comments (generated by `tools/build.rs`).

use seaglass::CardId;

include!(concat!(env!("OUT_DIR"), "/card_text.rs"));

/// The rules text of card `card_id`, if its source documents one.
pub fn card_text(card_id: CardId) -> Option<&'static str> {
    CARD_TEXT
        .binary_search_by_key(&card_id, |&(id, _)| id)
        .ok()
        .map(|i| CARD_TEXT[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;
    use seaglass::cards::minions::persistent_poet;

    #[test]
    fn minions_have_their_text() {
        assert_eq!(
            card_text(persistent_poet::ID),
            Some(
                "Divine Shield. Adjacent Dragons permanently keep Bonus Keywords and (double if \
                 Golden) stats gained in combat."
            )
        );
    }
}
